ge1(){return"\u0423\u0432\u044f\u0434\u0437\u0456\u0446\u0435 \u043f\u0430\u0440\u043e\u043b\u044c \u0442\u0443\u0442"},
gd8(a){return"\u041f\u0430\u0446\u0432\u0435\u0440\u0434\u0437\u0456\u0446\u044c"},
gev(){return"\u041f\u0430\u0440\u043e\u043b\u044c \u0430\u0431\u043e \u043a\u0430\u0440\u044b\u0441\u0442\u0430\u043b\u044c\u043d\u0456\u043a \u043d\u0435\u0434\u0430\u043f\u0443\u0448\u0447\u0430\u043b\u044c\u043d\u044b\u044f. \u041a\u0430\u043b\u0456 \u043b\u0430\u0441\u043a\u0430, \u0437\u0432\u044f\u0436\u044b\u0446\u0435\u0441\u044f \u0441\u0430 \u0441\u0432\u0430\u0456\u043c \u043a\u0456\u0440\u0430\u045e\u043d\u0456\u043a\u043e\u043c"},
