gew(){return"\u0422\u0430\u043a, \u0432\u044b \u043c\u043e\u0436\u0430\u0446\u0435 \u0441\u0442\u0432\u0430\u0440\u044b\u0446\u044c \u0440\u0430\u0445\u0443\u043d\u0430\u043a \u0441\u0442\u0432\u0430\u0440\u0430\u043b\u044c\u043d\u0456\u043a\u0430 \u044f\u043a \u043f\u0435\u0434\u0430\u0433\u043e\u0433 \u0430\u0431\u043e \u043f\u0440\u0430\u0444\u0435\u0441\u0456\u044f\u043d\u0430\u043b, \u043f\u0430\u0441\u043b\u044f \u0447\u0430\u0433\u043e \u043c\u044b \u043f\u0440\u0430\u0432\u044f\u0440\u0430\u0435\u043c \u0432\u0430\u0448 \u0434\u044b\u043f\u043b\u043e\u043c \u0446\u0456 \u0441\u0435\u0440\u0442\u044b\u0444\u0456\u043a\u0430\u0442, \u0456 \u0432\u044b \u043c\u043e\u0436\u0430\u0446\u0435 \u043f\u0430\u0447\u0430\u0446\u044c \u0434\u0437\u044f\u043b\u0456\u0446\u0446\u0430 \u0441\u0432\u0430\u0456\u043c \u043a\u0430\u043d\u0442\u044d\u043d\u0442\u0430\u043c \u0456 \u043f\u0440\u044b\u0446\u044f\u0433\u0432\u0430\u0446\u044c \u043d\u043e\u0432\u044b\u0445 \u043f\u0430\u0434\u043f\u0456\u0441\u0447\u044b\u043a\u0430\u045e. \u041a\u0430\u043b\u0456 \u045e \u0432\u0430\u0441 \u043d\u044f\u043c\u0430 \u0434\u044b\u043f\u043b\u043e\u043c\u0430 \u0446\u0456 \u0441\u0435\u0440\u0442\u044b\u0444\u0456\u043a\u0430\u0442\u0430, \u0432\u044b \u043c\u043e\u0436\u0430\u0446\u0435 \u0437\u0430\u0440\u0430\u0431\u043b\u044f\u0446\u044c \u0442\u043e\u043b\u044c\u043a\u0456 \u043f\u0440\u0430\u0437 \u0447\u0430\u0435\u0432\u044b\u0435."},
gep(){return"\u0426\u0456 \u0431\u044f\u0441\u043f\u0435\u0447\u043d\u0430\u044f \u0433\u044d\u0442\u0430\u044f \u043f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0430?"},
geo(){return"\u0422\u0430\u043a, \u043c\u044b \u043d\u0435 \u043f\u0440\u0430\u0434\u0430\u0435\u043c \u0432\u0430\u0448\u044b\u044f \u0434\u0430\u0434\u0437\u0435\u043d\u044b\u044f \u0442\u0440\u044d\u0446\u0456\u043c \u0430\u0441\u043e\u0431\u0430\u043c. \u0412\u044b \u043c\u043e\u0436\u0430\u0446\u0435 \u043c\u0435\u0446\u044c \u043f\u0440\u044b\u0432\u0430\u0442\u043d\u044b \u0440\u0430\u0445\u0443\u043d\u0430\u043a. \u041b\u044e\u0431\u043e\u0435 \u0447\u0430\u0442-\u043f\u0430\u0432\u0435\u0434\u0430\u043c\u043b\u0435\u043d\u043d\u0435 \u0437\u0430\u0446\u0432\u044f\u0440\u0434\u0436\u0430\u0435\u0446\u0446\u0430 \u0432\u0430\u043c\u0456 \u043f\u0430\u0441\u043b\u044f \u043f\u0435\u0440\u0448\u0430\u0433\u0430 \u043f\u0430\u0432\u0435\u0434\u0430\u043c\u043b\u0435\u043d\u043d\u044f. \u0427\u0430\u0442\u044b, \u043f\u0430\u0440\u043e\u043b\u0456 \u0456 \u0431\u0430\u043d\u043a\u0430\u045e\u0441\u043a\u0430\u044f \u0456\u043d\u0444\u0430\u0440\u043c\u0430\u0446\u044b\u044f \u0446\u0430\u043b\u043a\u0430\u043c \u0448\u044b\u0444\u0440\u0443\u044e\u0446\u0446\u0430. \u041c\u044b \u0431\u0430\u0447\u044b\u043c \u0432\u0430\u0448\u0443 \u0456\u043d\u0444\u0430\u0440\u043c\u0430\u0446\u044b\u044e \u0442\u043e\u043b\u044c\u043a\u0456 \u043f\u0440\u044b \u0441\u043a\u0430\u0440\u0433\u0430\u0445 \u0430\u0431\u043e \u043a\u0430\u043b\u0456 \u0432\u044b \u0440\u043e\u0431\u0456\u0446\u0435 \u0437\u0430\u043f\u044b\u0442 \u043d\u0430 \u0432\u044b\u0441\u043d\u043e\u0432\u0443."},
gej(){return"\u042f\u043a \u044f \u043c\u0430\u0433\u0443 \u0432\u0443\u0447\u044b\u0446\u0446\u0430 \u045e \u0433\u044d\u0442\u044b\u043c \u0434\u0430\u0434\u0430\u0442\u043a\u0443?"},
geb(){return"\u041f\u0430\u0434\u043f\u0456\u0448\u044b\u0446\u0435\u0441\u044f \u043d\u0430 \u0441\u0442\u0432\u0430\u0440\u0430\u043b\u044c\u043d\u0456\u043a\u0430 \u0456 \u0441\u043e\u0447\u044b\u0446\u0435 \u0437\u0430 \u043a\u0443\u0440\u0441\u0430\u043c\u0456 \u0456 \u0432\u0456\u0434\u044d\u0430\u043a\u0430\u043d\u0444\u0435\u0440\u044d\u043d\u0446\u044b\u044f\u043c\u0456. \u041a\u0443\u0440\u0441\u044b \u0441\u0442\u0432\u043e\u0440\u0430\u043d\u044b \u0434\u043b\u044f \u043d\u0430\u0432\u0443\u0447\u0430\u043d\u043d\u044f \u0456 \u043c\u043e\u0433\u0443\u0446\u044c \u0443\u043a\u043b\u044e\u0447\u0430\u0446\u044c \u043f\u044b\u0442\u0430\u043d\u043d\u0456 \u0432\u0456\u043a\u0442\u0430\u0440\u044b\u043d\u044b, \u0433\u0440\u0430\u0444\u0456\u043a\u0456, \u0441\u043a\u043b\u0430\u0434\u0430\u043d\u044b\u044f \u043c\u0430\u0442\u044d\u043c\u0430\u0442\u044b\u0447\u043d\u044b\u044f \u0440\u0430\u045e\u043d\u0430\u043d\u043d\u0456, \u0432\u0456\u0434\u044d\u0430, \u0430\u043d\u0456\u043c\u0456\u0440\u0430\u0432\u0430\u043d\u044b\u044f \u0433\u0456\u0441\u0442\u043e\u0440\u044b\u0456 \u0456 \u043f\u0430\u0434\u043a\u0430\u0441\u0442\u044b, \u044f\u043a\u0456\u044f \u0441\u0442\u0432\u0430\u0440\u0430\u044e\u0446\u044c \u043b\u0451\u0433\u043a\u0456 \u0456 \u043f\u0440\u0430\u0444\u0435\u0441\u0456\u0439\u043d\u044b \u0432\u043e\u043f\u044b\u0442 \u043d\u0430\u0432\u0443\u0447\u0430\u043d\u043d\u044f. \u041a\u043e\u0436\u043d\u044b \u043f\u0435\u0434\u0430\u0433\u043e\u0433 \u043c\u043e\u0436\u0430 \u0430\u0434\u0430\u043f\u0442\u0430\u0432\u0430\u0446\u044c \u0456\u0445 \u043f\u0430\u0434 \u043b\u044e\u0431\u0443\u044e \u0442\u044d\u043c\u0443. \u0412\u0456\u0434\u044d\u0430\u043a\u0430\u043d\u0444\u0435\u0440\u044d\u043d\u0446\u044b\u0456 \u0434\u043b\u044f \u0441\u0443\u0432\u044f\u0437\u0456, \u0430\u0446\u044d\u043d\u043a\u0456 \u0456 \u0437\u0432\u0430\u0440\u043e\u0442\u043d\u0430\u0439 \u0441\u0443\u0432\u044f\u0437\u0456."},
gdu(){return"\u041f\u0430\u043b\u0456\u0442\u044b\u043a\u0430 \u043f\u0440\u044b\u0432\u0430\u0442\u043d\u0430\u0441\u0446\u0456"},
